window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[201]={"id":"201","numero":201,"titre":"Transplantation d'organes","objectifs":[{"id":"201-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de donneurs potentiels","contenu":"<p>Un <span class=\"kw-def\">donneur potentiel</span> est toute personne — <strong>vivante</strong> ou <strong>décédée</strong> — chez qui un prélèvement d'organe(s) et/ou de tissu(s) peut être envisagé en vue d'une transplantation. En France, le principe est celui du <span class=\"kw-def\">consentement présumé</span>&nbsp;: <strong>toute personne décédée est considérée comme donneuse par défaut</strong>, sauf opposition exprimée de son vivant.</p>\n\n      <table >\n        <thead>\n          <tr><th>Catégorie de donneur</th><th>Définition</th><th>Particularité</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Donneur vivant</strong></td>\n            <td>Personne <span class=\"kw-def\">majeure</span>, non sous protection légale, faisant don d'un <span class=\"kw-clinique\">organe double</span> (rein, poumon) ou d'un organe <span class=\"kw-clinique\">susceptible de se régénérer</span> (foie)</td>\n            <td>Cercle de donneurs encadré par la loi ; don <span class=\"kw-clinique\">libre, gratuit, éclairé</span> (cf. obj-10)</td>\n          </tr>\n          <tr>\n            <td><strong>Donneur décédé en état de mort encéphalique (EME)</strong></td>\n            <td>Personne en <span class=\"kw-alerte\">destruction définitive et irréversible de l'encéphale</span>, avec perfusion des autres organes maintenue (cf. obj-5)</td>\n            <td>Situation <span class=\"kw-clinique\">la plus fréquente</span> des prélèvements multi-organes (PMO)</td>\n          </tr>\n          <tr>\n            <td><strong>Donneur décédé en arrêt circulatoire (« donneur à cœur arrêté »)</strong></td>\n            <td>Personne décédée en <span class=\"kw-alerte\">arrêt circulatoire persistant</span>, classée selon la <span class=\"kw-def\">classification de Maastricht</span> (cf. obj-8)</td>\n            <td>L'essentiel des prélèvements relève d'une procédure <strong>Maastricht 3</strong> (après limitation des thérapeutiques)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Bilan systématique du donneur potentiel (bilan pré-greffe).</strong> Il concerne <strong>tout type de donneur</strong> et recherche <span class=\"kw-clinique\">les</span> <span class=\"kw-ci\">contre-indications</span> ou les indications conditionnelles au don&nbsp;:\n        <ul>\n          <li><strong><span class=\"kw-etio\">Infectieux</span></strong> — <span class=\"kw-def\">dépistage</span> obl<span class=\"kw-chiffre\">iga</span>toire des maladies transmissibles&nbsp;: <span class=\"kw-clinique\">VIH1, VIH2, VHB, VHC, syphilis, HTLV1, CMV, EBV, <em>Toxoplasma gondii</em></span> ⭐. Attention&nbsp;: une pathologie transmissible n'est pas toujours une <span class=\"kw-ci\">contre-indication</span> (le <span class=\"kw-etio\">VIH</span> ou le <span class=\"kw-etio\">VHC</span> du donneur ne sont plus des CI formelles).</li>\n          <li><strong><span class=\"kw-etio\">Néoplasique</span></strong> — un antécédent de cancer est une <span class=\"kw-alerte\">contre-indication relative</span> au prélèvement ⭐ ; <span class=\"kw-imagerie\">TDM</span>-TAP systématique selon le collège.</li>\n          <li><strong>Qualité des organes</strong> — paramètres biologiques et morphologiques, <span class=\"kw-bio\">anatomopathologie</span> extemporanée possible (rein du donneur décédé), machine de perfusion, <span class=\"kw-clinique\">temps d'ischémie froide</span> (4&nbsp;h pour cœur/poumons, jusqu'à <span class=\"kw-chiffre\">36&nbsp;h</span> pour le rein).</li>\n          <li><strong>Autres</strong> — groupage sanguin, typage HLA, AC anti-HLA chez le receveur, évaluation cardiovasculaire.</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-ci\">Contre-indications</span> absolues au prélèvement (MIR).</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Maladie infectieuse transmissible non contrôlée ou évolutive</span> — <span class=\"kw-etio\">tuberculose</span> active, rage, <span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">VHC</span>, HTLV</li>\n          <li>Suspicion d'<span class=\"kw-alerte\">encéphalopathie spongiforme subaiguë</span> (Creutzfeldt-Jakob)</li>\n          <li><span class=\"kw-alerte\">Cancer ou hémopathie</span> (sauf certains cancers anciens guéris)</li>\n        </ul>\n      </div>","frequence":0},{"id":"201-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition des tissus et organes transplantés","contenu":"<table >\n        <thead>\n          <tr><th>Terme</th><th>Définition</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Transplantation d'organe</strong></td>\n            <td>Opération chirurgicale <strong>nécessitant des sutures vasculaires</strong>, consistant à <span class=\"kw-def\">remplacer un organe vital défaillant par un organe sain</span> — appelé <span class=\"kw-clinique\">greffon</span> ou <span class=\"kw-clinique\">transplant</span> — prélevé chez un donneur.</td>\n          </tr>\n          <tr>\n            <td><strong>Greffe de tissus</strong></td>\n            <td>\n              Opération permettant une <span class=\"kw-def\">reconstruction tissulaire</span> par greffe de tissus sains (<span class=\"kw-clinique\">cornée, peau, os, vaisseau</span>), prélevés chez un donneur décédé ou vivant.\n              <ul>\n                <li><strong>Greffe de tissus composites</strong> (visage, membres)&nbsp;: particularité de nécessiter des <span class=\"kw-clinique\">sutures vasculaires ET nerveuses</span></li>\n                <li><strong>Greffe d'îlots de Langerhans</strong> (pancréatiques)&nbsp;: acceptée dans le soin courant pour des indications bien circonscrites</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Distinction clé.</strong> La <span class=\"kw-def\">transplantation</span> implique des <strong>sutures vasculaires</strong> (rétablissement immédiat de la vascularisation du greffon). La <span class=\"kw-def\">greffe</span> de tissus repose sur une simple apposition tissulaire — <strong>sauf</strong> la greffe de tissus composites, qui requiert également des anastomoses vasculaires et nerveuses.\n      </div>\n\n      <h4 style=\"margin: 0.8em 0 0.3em; color: var(--ink);\">Principales indications selon l'organe</h4>\n\n      <table >\n        <thead>\n          <tr><th>Organe</th><th>Indications principales</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Rein</strong></td>\n            <td><span class=\"kw-ci\">Insuffisance rénale</span> terminale (<span class=\"kw-chiffre\">DFG &lt; 15 mL/min</span>)&nbsp;: transplantation <span class=\"kw-clinique\">préemptive</span> (avant l'épuration extra-rénale) ou après initiation de la dialyse</td>\n          </tr>\n          <tr>\n            <td><strong>Foie</strong></td>\n            <td><span class=\"kw-alerte\">Hépatite fulminante</span> · cirrhose Child C · hépatocarcinome (selon nombre/taille) · maladies cholestasiques chroniques (atrésie des voies biliaires) · maladies métaboliques (déficit enzymatique)</td>\n          </tr>\n          <tr>\n            <td><strong>Cœur</strong></td>\n            <td><span class=\"kw-ci\">Insuffisance cardiaque</span> terminale réfractaire au traitement médical optimal (décision fondée sur des scores type <span class=\"kw-clinique\">Intermacs</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Pancréas</strong></td>\n            <td>DT1 instable (hypoglycémies fréquentes/sévères) · DT1 compliqué d'<span class=\"kw-ci\">insuffisance rénale</span> → transplantation <span class=\"kw-clinique\">pancréas + rein</span> simultanée ou différée</td>\n          </tr>\n          <tr>\n            <td><strong>Poumons</strong></td>\n            <td>Mucoviscidose, fibroses, HTAP primitive, emphysème, BPCO — si échec du traitement médical + espérance de vie <span class=\"kw-chiffre\">&lt; 2 ans</span> sans greffe et <span class=\"kw-chiffre\">&gt; 2 ans</span> avec greffe</td>\n          </tr>\n          <tr>\n            <td><strong>Intestin</strong></td>\n            <td>Insuffisance intestinale (syndrome du grêle court, malformation <span class=\"kw-etio\">congénitale</span>, maladies inflammatoires)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Question d'annale — transplantation rénale.</strong>\n        <ul>\n          <li><strong>Où implante-t-on le greffon ?</strong> En <span class=\"kw-clinique\">fosse iliaque</span> (et non lombaire)&nbsp;: vaisseaux et vessie d'accès facile, anastomoses sur <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">vaisseaux iliaques externes</span>, implantation urétérale dans la vessie avec montage anti-reflux (sonde double JJ).</li>\n          <li><strong>Quels équipements en post-opératoire ?</strong> <span class=\"kw-clinique\">Sonde vésicale</span> <span class=\"kw-clinique\">les</span> 1ᵉʳˢ jours (vérifier la reprise de diurèse) ; <span class=\"kw-clinique\">sonde JJ</span> les 1ʳᵉˢ semaines (cicatrisation de l'anastomose urétéro-vésicale).</li>\n          <li><strong>Quand débuter l'anti-rejet ?</strong> Traitement d'induction <span class=\"kw-alerte\">dès la réalisation de la greffe</span> (on n'attend pas la reprise de diurèse).</li>\n          <li><strong>Taux de succès ?</strong> <span class=\"kw-chiffre\">90 % à 1 an</span> · <span class=\"kw-chiffre\">60 % à 10 ans</span>.</li>\n        </ul>\n      </div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/renal-transplant","label":"Radiopaedia : Renal transplant"}]},{"id":"201-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les principales règles de compatibilité immunologique nécessaire pour envisager une transplantation d’organe : groupe sanguin et tissulaire (HLA)","contenu":"<p>La compatibilité immunologique repose sur l'appariement de <strong>2 systèmes</strong>&nbsp;: le <span class=\"kw-def\">groupe sanguin ABO</span> et le <span class=\"kw-def\">groupe tissulaire HLA</span>. Le <span class=\"kw-clinique\">rhésus n'est pas pris en compte</span> ❌.</p>\n\n      <h4 style=\"margin: 0.4em 0 0.3em; color: var(--ink);\">Le système HLA</h4>\n      <p><span class=\"kw-clinique\">Les</span> molécules <span class=\"kw-def\">HLA</span> (Human Leukocyte Antigens) sont codées par des gènes du <span class=\"kw-clinique\">chromosome 6</span> et expriment le complexe majeur d'histocompatibilité (CMH), divisé en CMH-I, CMH-II et CMH-III. Le CMH permet de distinguer le <span class=\"kw-def\">soi</span> du <span class=\"kw-def\">non-soi</span> ; il présente des peptides aux récepteurs des <span class=\"kw-bio\">lymphocytes</span> T (TCR).</p>\n      <ul>\n        <li><strong>CMH-I</strong> (<span class=\"kw-clinique\">HLA-A, -B, -C</span>) — ubiquitaire, présent sur <strong>toutes <span class=\"kw-clinique\">les</span> cellules nucléées</strong> ; présente aux <span class=\"kw-clinique\">LT CD8+</span></li>\n        <li><strong>CMH-II</strong> (<span class=\"kw-clinique\">HLA-DR, -DQ, -DP</span>) — uniquement <span class=\"kw-clinique\">les</span> <strong>cellules présentatrices d'<span class=\"kw-bio\">antigène</span></strong> (LB, <span class=\"kw-bio\">monocytes</span>, macrophages, cellules dendritiques, LT activés) ; présente aux <span class=\"kw-clinique\">LT CD4+</span>. En cas d'inflammation, le CMH-II peut apparaître sur l'endothélium, les cellules rénales proximales, l'épithélium cutané, les entérocytes.</li>\n      </ul>\n\n      <table >\n        <thead>\n          <tr><th>Système</th><th>Règle de compatibilité</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Groupe sanguin ABO</strong></td>\n            <td>\n              <ul>\n                <li>Groupe <span class=\"kw-clinique\">rhésus non pris en compte</span> ❌</li>\n                <li>Transplantations <span class=\"kw-def\">ABO-incompatibles</span> possibles dans certains cas, après <strong>protocole de désensibilisation</strong>&nbsp;: réduire le titre d'alloanticorps (<span class=\"kw-ttt\">plasmaphérèse</span>, <span class=\"kw-ttt\">rituximab</span>) et neutraliser leur effet cytotoxique (<span class=\"kw-ttt\">immunoglobulines polyvalentes</span>, <span class=\"kw-ttt\">bloqueurs du complément</span>)</li>\n                <li>ABO-incompatible <strong>sans désensibilisation</strong> → <span class=\"kw-alerte\">rejet hyperaigu avec nécrose immédiate du greffon</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Groupe tissulaire HLA</strong></td>\n            <td>\n              <ul>\n                <li><strong>Typage HLA</strong> du <span class=\"kw-clinique\">donneur ET du receveur</span></li>\n                <li><strong>Recherche d'AC anti-HLA</strong> chez le <span class=\"kw-clinique\">receveur</span>, <span class=\"kw-chiffre\">tous les 3 mois</span> pendant l'attente. Ces AC peuvent apparaître après <span class=\"kw-clinique\">grossesse, transfusion, transplantation antérieure</span> → <span class=\"kw-alerte\">facteur de risque majeur de rejet humoral</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin: 0.8em 0 0.3em; color: var(--ink);\">Le cross-match (épreuve de compatibilité croisée)</h4>\n\n      <table >\n        <thead>\n          <tr><th></th><th>Cross-match virtuel (MIR)</th><th>Cross-match réel</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Objectif</strong></td>\n            <td>Comparer <span class=\"kw-clinique\">les</span> AC anti-HLA du receveur au système HLA du donneur</td>\n            <td>Identifier dans le sérum du receveur des <span class=\"kw-clinique\">AC cytotoxiques</span> dirigés contre <span class=\"kw-clinique\">les</span> antigènes du donneur</td>\n          </tr>\n          <tr>\n            <td><strong>Principe</strong></td>\n            <td>Incubation du sérum du receveur avec des <span class=\"kw-clinique\">microbilles</span> portant des antigènes HLA</td>\n            <td>Incubation, en présence de <span class=\"kw-bio\">complément</span>, du sérum du receveur + <span class=\"kw-bio\">lymphocytes</span> du donneur (ganglion)</td>\n          </tr>\n          <tr>\n            <td><strong>Quand / intérêt</strong></td>\n            <td>Sa <strong>négativité permet de ne pas attendre le cross-match réel</strong> (qui allonge le temps d'ischémie froide)</td>\n            <td><strong>Systématique juste avant la greffe</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Interprétation</strong></td>\n            <td>—</td>\n            <td>Absence de lyse = <span class=\"kw-clinique\">négatif</span> → transplantation possible · Lyse cellulaire = <span class=\"kw-alerte\">positif</span> → <strong>contre-indique la transplantation</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Acteurs de la réaction allo-immune.</strong>\n        <ul>\n          <li><strong>Chez le donneur</strong> — le <span class=\"kw-clinique\">CMH</span> à la surface des cellules du greffon est la principale cible immunitaire (molécules « <span class=\"kw-def\">non-soi</span> »)</li>\n          <li><strong>Chez le receveur</strong> — <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">LT</span> jouent un rôle majeur dans le <strong>rejet cellulaire</strong> (<span class=\"kw-ttt\">infiltration</span> du greffon, attaque de l'épithélium tubulaire) ; les <span class=\"kw-clinique\">LB</span> jouent un rôle majeur dans le <strong>rejet humoral</strong> (AC anti-HLA ciblant l'endothélium capillaire)</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Attribution du greffon (Agence de la Biomédecine).</strong> La compatibilité HLA intervient de 2 manières&nbsp;: un <span class=\"kw-clinique\">très bon niveau de compatibilité</span> favorise l'attribution ; la présence d'<span class=\"kw-alerte\">AC anti-HLA du receveur dirigés contre les antigènes du donneur</span> à taux importants constitue un obstacle à l'attribution.\n      </div>","frequence":3},{"id":"201-4","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les aspects épidémiologiques, les résultats des transplantations d’organe et l’organisation administrative","contenu":"<div class=\"callout callout-danger\">\n        <strong>Pénurie d'organes.</strong> Il existe en France une <span class=\"kw-alerte\">pénurie d'organes</span>&nbsp;: <span class=\"kw-clinique\">les</span> besoins excèdent largement les possibilités de transplantation. Environ <span class=\"kw-chiffre\">25 %</span> des patients pourront espérer être transplantés dans l'année.\n      </div>\n\n      <table >\n        <thead>\n          <tr><th>Aspect</th><th>Éléments à connaître</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Pénurie</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-chiffre\">~25 %</span> des patients transplantés dans l'année</li>\n                <li>Augmentation des inscriptions (et des décès sur liste d'attente)</li>\n                <li>Taux d'opposition au prélèvement en France <span class=\"kw-chiffre\">≈ 32 %</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Résultats</strong></td>\n            <td>\n              <ul>\n                <li>Augmentation de l'activité de greffe (plus d'organes transplantés)</li>\n                <li>La transplantation <strong>améliore la qualité de vie et prolonge la survie</strong> (survie <span class=\"kw-clinique\">actuarielle</span> du greffon et du receveur, variable selon l'organe)</li>\n                <li>Résultats des <span class=\"kw-clinique\">donneurs vivants</span> excellents à long terme et <strong>supérieurs</strong> à ceux des donneurs décédés</li>\n                <li>Complications chirurgicales et <span class=\"kw-def\">incidence</span> des rejets aigus/chroniques varient selon l'organe</li>\n                <li>Greffe de donneur vivant <span class=\"kw-def\">ABO-incompatible</span> développée avec succès depuis quelques années</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin: 0.8em 0 0.3em; color: var(--ink);\">Organisation administrative</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Missions de l'Agence de la Biomédecine (ABM).</strong> Elle est chargée de l'organisation administrative de la transplantation&nbsp;:\n        <ul>\n          <li>Gestion de la <strong>liste nationale d'attente</strong> (selon un système de <span class=\"kw-def\">score</span>)</li>\n          <li>Gestion du <strong>registre national des refus (RNR)</strong></li>\n          <li>Gestion du système national d'information <span class=\"kw-clinique\">CRISTAL</span> — données anonymes des receveurs et donneurs, traçabilité précise des organes jusqu'au receveur, évaluation des résultats</li>\n          <li>Coordonner <span class=\"kw-clinique\">les</span> prélèvements, la <strong>répartition et l'attribution</strong> des organes (système de <span class=\"kw-def\">score</span>)</li>\n          <li>Évaluer <span class=\"kw-clinique\">les</span> activités médicales des équipes de transplantation</li>\n          <li>Promouvoir la recherche, le don d'organes et l'information du public</li>\n          <li>Veiller à l'application des grands principes éthiques des lois de bioéthique</li>\n          <li>Évaluation médico-économique de l'activité de prélèvement et de greffe</li>\n        </ul>\n      </div>\n\n      <table >\n        <thead>\n          <tr><th>Étape</th><th>Règles</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Inscription sur liste d'attente</strong></td>\n            <td>Le patient ne peut être greffé que s'il est <span class=\"kw-clinique\">couvert par la Sécurité sociale</span> ET <span class=\"kw-clinique\">inscrit sur la liste nationale</span> enregistrée auprès de l'ABM</td>\n          </tr>\n          <tr>\n            <td><strong>Règles d'attribution</strong></td>\n            <td>\n              Répondent au <span class=\"kw-def\">principe d'utilité</span> (efficacité) et au <span class=\"kw-def\">principe de justice</span> (équité)&nbsp;:\n              <ul>\n                <li><strong>Critères médicaux</strong> — compatibilité (ABO, HLA), adéquation (temps d'ischémie froide le plus court)</li>\n                <li><strong>Critères d'équité</strong> — durée d'attente</li>\n                <li><strong><span class=\"kw-def\">Critères de</span> taille</strong> donneur/receveur (importants pour le thorax et le foie)</li>\n                <li><strong><span class=\"kw-def\">Critères de</span> priorité</strong> — receveur <span class=\"kw-clinique\">pédiatrique</span>, degré d'<span class=\"kw-alerte\">urgence</span> (ex. <span class=\"kw-alerte\">hépatite fulminante</span>), difficulté à trouver un receveur compatible (ex. <span class=\"kw-clinique\">receveur hyperimmunisé</span>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Score</span></strong></td>\n            <td>Système de <span class=\"kw-def\">score</span> intégrant <span class=\"kw-clinique\">les</span> paramètres d'appariement donneur/receveur, calculé à chaque greffon disponible, qui permet d'attribuer le greffon</td>\n          </tr>\n        </tbody>\n      </table>","frequence":1},{"id":"201-5","rang":"A","rubrique":"Définition","titre":"Connaître les grands principes de la loi de bio-éthique concernant le don d’organe","contenu":"<p>L'activité de transplantation est encadrée par des lois spécifiques au prélèvement depuis <span class=\"kw-chiffre\">1976</span> (loi Caillavet), remplacées par <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">lois de bioéthique</span> (1994), régulièrement révisées (<span class=\"kw-chiffre\">2004, 2011, 2021</span>).</p>\n\n      <h4 style=\"margin: 0.4em 0 0.3em; color: var(--ink);\">Repères historiques de la législation</h4>\n\n      <table >\n        <thead>\n          <tr><th>Texte</th><th>Apport principal</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Circulaire Jeanneney (1968)</strong></td>\n            <td>Définition des <span class=\"kw-clinique\">critères de mort cérébrale</span></td>\n          </tr>\n          <tr>\n            <td><strong>Loi Caillavet (1976)</strong></td>\n            <td><span class=\"kw-def\">Consentement présumé</span> pour le donneur décédé ; choix librement et expressément consenti pour le donneur vivant</td>\n          </tr>\n          <tr>\n            <td><strong>Loi de bioéthique (1994)</strong></td>\n            <td>Donneurs vivants majeurs et <span class=\"kw-clinique\">apparentés</span> (parents, enfants, fratrie) ; donneurs décédés non inscrits au <span class=\"kw-clinique\">registre national des refus</span> ; création de l'Établissement français des Greffes (EfG)</td>\n          </tr>\n          <tr>\n            <td><strong>1ʳᵉ révision (2004)</strong></td>\n            <td><strong>Élargissement du cercle des donneurs vivants</strong> (grands-parents, oncle/tante, cousin germain, conjoint, toute personne prouvant une <span class=\"kw-clinique\">vie commune ≥ 2 ans</span>) ; comités donneurs vivants ; <span class=\"kw-def\">suivi</span> annuel des donneurs</td>\n          </tr>\n          <tr>\n            <td><strong>2ᵉ révision (2011)</strong></td>\n            <td>Élargissement à toute personne prouvant un <span class=\"kw-clinique\">lien affectif étroit et stable ≥ 2 ans</span> ; <strong>dons croisés</strong> de reins (limités à 2 couples) ; protection sociale des donneurs vivants</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-clinique\">Les</span> grands principes transverses des lois de bioéthique.</strong>\n        <ul>\n          <li><strong>Gratuité</strong> du don ⭐ et <span class=\"kw-clinique\">interdiction de toute publicité</span></li>\n          <li><strong>Anonymat</strong> donneur ↔ receveur (cf. obj-9 pour <span class=\"kw-clinique\">les</span> dérogations)</li>\n          <li><strong>Consentement présumé</strong> pour le donneur décédé / consentement libre et éclairé pour le donneur vivant</li>\n          <li><strong>Respect dû au corps</strong> — obl<span class=\"kw-chiffre\">iga</span>tion de « <span class=\"kw-clinique\">s'assurer de la meilleure restauration possible du corps</span> »</li>\n          <li>Modalités de constatation de la mort, liste des établissements autorisés, obl<span class=\"kw-chiffre\">iga</span>tion d'informer <span class=\"kw-clinique\">les</span> proches</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> La <strong>loi Caillavet (1976)</strong> introduit le <span class=\"kw-def\">consentement présumé</span> ; la <strong>loi de bioéthique de 1994</strong> structure le dispositif moderne (registre des refus, encadrement du donneur vivant). <span class=\"kw-clinique\">Les</span> révisions successives <strong>élargissent progressivement le cercle des donneurs vivants</strong>.\n      </div>","frequence":1},{"id":"201-6","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la mort encéphalique","contenu":"<div class=\"callout callout-danger\">\n        <strong>Définition.</strong> L'état de <span class=\"kw-def\">mort encéphalique</span> (mort cérébrale, EME) est la <span class=\"kw-alerte\">destruction définitive et irréversible de l'encéphale</span>, <strong>avec perfusion des autres organes maintenue</strong>. Ses <span class=\"kw-def\">critères diagnostiques</span> ont une <strong>valeur médico-légale</strong>.\n      </div>\n\n      <table >\n        <thead>\n          <tr><th>Élément</th><th>Donnée</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Fréquence</strong></td>\n            <td>Représente <span class=\"kw-chiffre\">&lt; 1 %</span> des décès</td>\n          </tr>\n          <tr>\n            <td><strong>Principales causes</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-etio\">AVC</span> — <span class=\"kw-chiffre\">&gt; 50 %</span> des causes</li>\n                <li>Accidents de la circulation et autres traumatismes</li>\n                <li><span class=\"kw-etio\">Anoxies cérébrales</span> (pendaisons, noyades…)</li>\n                <li><span class=\"kw-etio\">Intoxications</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Clé conceptuelle.</strong> La spécificité de la mort encéphalique est la <strong>dissociation</strong> entre un encéphale <span class=\"kw-alerte\">définitivement détruit</span> et des organes périphériques <span class=\"kw-clinique\">encore perfusés</span> (cœur battant, <span class=\"kw-ttt\">ventilation mécanique</span>) — c'est précisément ce qui rend possible le prélèvement multi-organes. <span class=\"kw-clinique\">Les</span> <em>critères</em> diagnostiques sont détaillés dans l'objectif suivant (obj-6).\n      </div>","frequence":0},{"id":"201-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les critères de mort encéphalique","contenu":"<div class=\"callout callout-warn\">\n        <strong>Préalable indispensable (MIR).</strong> Avant toute évaluation, il faut s'assurer de l'<strong>absence d'éléments interférant</strong> avec l'examen neurologique&nbsp;: pas de <span class=\"kw-clinique\">sédation</span> ni de <span class=\"kw-clinique\">curarisation</span>, pas de troubles hydroélectrolytiques sévères, pas d'<span class=\"kw-clinique\">hypothermie</span> (objectif <span class=\"kw-chiffre\">T &gt; 35 °C</span>), pas d'<span class=\"kw-clinique\">hypotension</span> (objectif <span class=\"kw-chiffre\">PAM &gt; 65 mmHg</span>).\n      </div>\n\n      <table >\n        <thead>\n          <tr><th>Type de critères</th><th>Contenu</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Critères cliniques</span></strong></td>\n            <td>\n              <ul>\n                <li>Absence totale de conscience et d'activité motrice spontanée → <span class=\"kw-clinique\">Glasgow = 3</span></li>\n                <li>Abolition de <strong>tous <span class=\"kw-clinique\">les</span> réflexes du tronc cérébral</strong> → <span class=\"kw-clinique\">score de Liège = 0</span> (cornéen &gt; photomoteur &gt; oculocéphalogyre &gt; cochléovestibulaire &gt; oculocardiaque &gt; <span class=\"kw-clinique\">toux</span>)</li>\n                <li><strong>Absence de ventilation spontanée</strong> malgré une épreuve d'hypercapnie (<span class=\"kw-chiffre\">PaCO₂ ≥ 55–60 mmHg</span> sur <span class=\"kw-bio\">GDS</span>), apport en O₂ maintenu, à distance de tout sédatif — sa positivité signe la <span class=\"kw-alerte\">mort du tronc cérébral</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Critères paracliniques</strong> (absence d'activité cérébrale)</td>\n            <td>\n              <ul>\n                <li>Soit <strong><span class=\"kw-imagerie\">EEG</span></strong> — <span class=\"kw-bio\">2 EEG</span> à <span class=\"kw-chiffre\">≥ 4 h</span> d'intervalle, <span class=\"kw-clinique\">nuls et aréactifs</span> sur <span class=\"kw-chiffre\">30 min</span> (en l'absence d'<span class=\"kw-clinique\">hypothermie</span> ou de dépresseur de l'activité cérébrale type barbiturique)</li>\n                <li>Soit <span class=\"kw-imagerie\">angioscanner / angio-IRM / artériographie</span> (si <span class=\"kw-imagerie\">EEG</span> non contributif) → <span class=\"kw-alerte\">absence de circulation cérébrale</span>&nbsp;: pas d'opacification des <span class=\"kw-clinique\">artères cérébrales moyennes</span> ni des <span class=\"kw-clinique\">veines profondes</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Distracteur à connaître ⚠️.</strong> L'<span class=\"kw-alerte\">absence d'activité hémodynamique</span> ne fait <strong>PAS</strong> partie des éléments à rechercher pour le diagnostic de mort encéphalique (par définition, la perfusion des organes est maintenue).\n      </div>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/brain-death","label":"Radiopaedia : Brain death"}]},{"id":"201-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principales classes d’immunosuppresseurs utilisés en transplantation d’organe","contenu":"<p>L'objectif du traitement est la <span class=\"kw-def\">prévention du rejet du greffon</span>, qui survient <strong>inéluctablement</strong> en l'absence d'immunosuppression. La cible principale est l'<span class=\"kw-clinique\">activation et la prolifération des lymphocytes T</span> ; <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">immunosuppresseurs</span> ciblant le LB y sont associés dans de rares cas (rejets humoraux).</p>\n\n      <h4 style=\"margin: 0.4em 0 0.3em; color: var(--ink);\">Cibles moléculaires (cascade d'activation du LT)</h4>\n\n      <table >\n        <thead>\n          <tr><th>Étape ciblée</th><th>Molécule</th><th>Classe</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Signal de <strong>costimulation</strong> (CD80/CD86 – CD28)</td>\n            <td><span class=\"kw-ttt\">bélatacept</span></td>\n            <td>Inhibiteur de costimulation</td>\n          </tr>\n          <tr>\n            <td>Activation de la <strong>calcineurine</strong> (→ NFAT)</td>\n            <td><span class=\"kw-ttt\">ciclosporine</span>, <span class=\"kw-ttt\">tacrolimus</span></td>\n            <td><span class=\"kw-def\">Inhibiteurs de la calcineurine (ICN)</span></td>\n          </tr>\n          <tr>\n            <td>Fixation de l'<strong>IL-2</strong> sur son récepteur</td>\n            <td><span class=\"kw-ttt\">basiliximab</span></td>\n            <td>Anti-récepteur de l'IL-2 (anti-CD25)</td>\n          </tr>\n          <tr>\n            <td>Voie intracellulaire <strong>mTOR</strong></td>\n            <td><span class=\"kw-ttt\">évérolimus</span>, <span class=\"kw-ttt\">sirolimus</span></td>\n            <td>Inhibiteurs de mTOR</td>\n          </tr>\n          <tr>\n            <td>Synthèse des <strong>bases puriques/pyrimidiques</strong> (prolifération)</td>\n            <td><span class=\"kw-ttt\">azathioprine</span>, <span class=\"kw-ttt\">mycophénolate</span></td>\n            <td>Antiprolifératifs / antimétabolites</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin: 0.8em 0 0.3em; color: var(--ink);\">Schéma thérapeutique</h4>\n\n      <table >\n        <thead>\n          <tr><th>Phase</th><th>Objectif</th><th>Molécules</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Traitement d'induction</strong></td>\n            <td>Prévenir le rejet aigu à la phase initiale par une immunosuppression <strong>forte</strong> <span class=\"kw-clinique\">les</span> 1ᵉʳˢ jours</td>\n            <td><span class=\"kw-ttt\">AC polyclonaux déplétants</span> (patients à haut risque immunologique) ou <span class=\"kw-ttt\">AC monoclonal non déplétant</span> (basiliximab)</td>\n          </tr>\n          <tr>\n            <td><strong>Traitement d'entretien</strong></td>\n            <td>Prévenir le rejet aigu sur le long terme, avec la <strong>plus faible iatrogénie</strong> possible</td>\n            <td>\n              Schéma de référence = <strong><span class=\"kw-ttt\">trithérapie</span></strong>&nbsp;:\n              <ul>\n                <li><span class=\"kw-ttt\">Corticoïdes</span></li>\n                <li>Antiprolifératif — <span class=\"kw-ttt\">mycophénolate</span></li>\n                <li>Inhibiteur de la calcineurine — <span class=\"kw-ttt\">tacrolimus</span> ou <span class=\"kw-ttt\">ciclosporine</span></li>\n              </ul>\n              <em>Schémas alternatifs</em>&nbsp;: limiter <span class=\"kw-clinique\">les</span> EI des <span class=\"kw-ttt\">corticoïdes</span> (arrêt ou protocole sans <span class=\"kw-ttt\">corticoïdes</span>) ou la néphrotoxicité des ICN (<span class=\"kw-ttt\">inhibiteurs de mTOR</span> ou <span class=\"kw-ttt\">bélatacept</span>).\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Règles de prescription incontournables.</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Ne JAMAIS arrêter le traitement immunosuppresseur</span> ❌</li>\n          <li>Attention aux <span class=\"kw-alerte\">interactions médicamenteuses</span> ⚠️, surtout avec <span class=\"kw-clinique\">les</span> inhibiteurs/inducteurs enzymatiques du <span class=\"kw-bio\">cytochrome P450 3A4</span></li>\n          <li><strong>Monitoring pharmacologique</strong> pour <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">immunosuppresseurs</span> à <span class=\"kw-clinique\">marge thérapeutique étroite</span> (dosage de la concentration sanguine)</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Le rejet — typologie (pour situer <span class=\"kw-clinique\">les</span> cibles thérapeutiques).</strong>\n        <ul>\n          <li><strong>Rejet hyperaigu humoral</strong> — AC anti-HLA <span class=\"kw-alerte\">préformés</span> ; thrombose du greffon en quelques <span class=\"kw-chiffre\">minutes</span> à <span class=\"kw-chiffre\">4–5 jours</span> ; transplantectomie souvent nécessaire</li>\n          <li><strong>Rejet aigu cellulaire</strong> — <span class=\"kw-ttt\">infiltration</span> lymphocytaire ; favorisé par l'<span class=\"kw-clinique\">inobservance</span> ; traité par <span class=\"kw-ttt\">corticostéroïdes fortes doses</span> ; bon <span class=\"kw-def\">pronostic</span></li>\n          <li><strong>Rejet aigu humoral</strong> — AC anti-HLA du donneur + dépôt de <span class=\"kw-clinique\">C4d</span> ; traité par <span class=\"kw-ttt\">échanges plasmatiques + Ig polyvalentes ± rituximab</span> ; <span class=\"kw-def\">pronostic</span> médiocre</li>\n          <li><strong>Rejet chronique</strong> — altération progressive de la fonction du greffon (médiation cellulaire ou humorale)</li>\n        </ul>\n      </div>","frequence":2},{"id":"201-9","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les particularités diagnostiques de la mort encéphalique ; Le donneur à cœur arrêté","contenu":"<h4 style=\"margin: 0.4em 0 0.3em; color: var(--ink);\">Particularités du prélèvement chez le donneur en mort encéphalique</h4>\n\n      <table >\n        <thead>\n          <tr><th>Aspect</th><th>Règle</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Constat / procès-verbal de décès</strong></td>\n            <td>Établis par <span class=\"kw-clinique\">2 médecins</span> qui <strong>ne doivent pas appartenir à la même unité fonctionnelle (UF) ou au même service</strong> que <span class=\"kw-clinique\">les</span> médecins réalisant le prélèvement ou la greffe</td>\n          </tr>\n          <tr>\n            <td><strong>Opposition</strong></td>\n            <td>Consultation du <span class=\"kw-clinique\">registre des refus</span> (sinon présomption de consentement)</td>\n          </tr>\n          <tr>\n            <td><strong>Famille</strong></td>\n            <td>Si le défunt n'est pas inscrit au registre, un proche peut faire part de son opposition&nbsp;: <span class=\"kw-clinique\">témoignage écrit, daté et signé</span></td>\n          </tr>\n          <tr>\n            <td><strong>Cas particuliers</strong></td>\n            <td>\n              <ul>\n                <li>Majeur protégé → consentement écrit du <span class=\"kw-clinique\">tuteur</span></li>\n                <li>Mineur ⭐ → consentement écrit de <strong>chacun</strong> des titulaires de l'autorité parentale (ou du tuteur) ; si impossibilité de consulter l'un d'eux, <span class=\"kw-clinique\">1 seul suffit</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin: 0.8em 0 0.3em; color: var(--ink);\">Le donneur à cœur arrêté (arrêt circulatoire persistant)</h4>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-def\">Classification</span> de Maastricht.</strong>\n        <ul>\n          <li><strong>Catégorie 1</strong> — <span class=\"kw-alerte\">ACR</span> hors de tout contexte de PEC médicalisée, décès constaté à la PEC (définition du T0 majeure)</li>\n          <li><strong>Catégorie 2</strong> — <span class=\"kw-alerte\">ACR</span> avec MCE + ventilation efficaces, mais sans récupération d'activité circulatoire</li>\n          <li><strong>Catégorie 3</strong> — décision de <span class=\"kw-clinique\">limitation des thérapeutiques (LAT)</span> en <span class=\"kw-alerte\">réanimation</span> → <strong>l'essentiel des prélèvements à cœur arrêté</strong></li>\n          <li><strong>Catégorie 4</strong> — décès en mort encéphalique avec arrêt circulatoire irréversible au cours de la PEC en <span class=\"kw-alerte\">réanimation</span></li>\n        </ul>\n      </div>\n\n      <table >\n        <thead>\n          <tr><th></th><th>Donneur à cœur arrêté</th><th><em>Rappel : mort encéphalique</em></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Preuve du décès</strong></td>\n            <td>Enregistrement <span class=\"kw-imagerie\">ECG</span> pendant <span class=\"kw-chiffre\">5 min</span>&nbsp;: <span class=\"kw-clinique\">pas de QRS</span> ou complexes agoniques <span class=\"kw-chiffre\">&lt; 5/min</span></td>\n            <td><span class=\"kw-def\">Critères cliniques</span> + paracliniques (cf. obj-6)</td>\n          </tr>\n          <tr>\n            <td><strong>Procès-verbal</strong></td>\n            <td><span class=\"kw-clinique\">1 seul médecin</span></td>\n            <td><span class=\"kw-clinique\">2 médecins</span></td>\n          </tr>\n          <tr>\n            <td><strong>Registre des refus</strong></td>\n            <td>Interrogation <span class=\"kw-alerte\">immédiate et obligatoire</span> du RNR</td>\n            <td>Consultation du registre des refus</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Receveur.</strong> Le receveur d'un greffon issu d'un donneur à cœur arrêté consent à recevoir un greffon « à <span class=\"kw-clinique\">critères élargis</span> » — il reste inscrit sur la liste nationale.\n      </div>","frequence":0},{"id":"201-10","rang":"A","rubrique":"Définition","titre":"Connaître les principes éthiques et légaux en matière de don d’organes","contenu":"<table >\n        <thead>\n          <tr><th>Principe</th><th>Contenu</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Gratuité</strong></td>\n            <td>Principe de <span class=\"kw-clinique\">gratuité</span> des dons ; <strong>interdiction de toute publicité</strong> ; prise en charge des frais (pas de rémunération, même en cas de pénurie)</td>\n          </tr>\n          <tr>\n            <td><strong>Anonymat</strong></td>\n            <td>\n              Anonymat donneur ↔ receveur (le nom ne peut être communiqué). Applicable aux <span class=\"kw-clinique\">donneurs décédés</span>, de <span class=\"kw-clinique\">moelle osseuse</span>, de <span class=\"kw-clinique\">sang</span>, de <span class=\"kw-clinique\">gamètes</span>. La famille du donneur peut être informée des organes prélevés et du résultat des greffes si elle le demande.\n              <br><strong>2 dérogations</strong>&nbsp;: don sur personne vivante au sein d'une famille ; nécessité thérapeutique (seuls <span class=\"kw-clinique\">les</span> médecins du donneur et du receveur accèdent à l'identification).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Consentement présumé</strong></td>\n            <td>\n              <strong>Toute personne décédée est donneuse par défaut</strong>, sauf souhait contraire exprimé de son vivant&nbsp;:\n              <ul>\n                <li>Inscription sur le <span class=\"kw-clinique\">registre national des refus</span> (tenu par l'ABM, révocable, conditions&nbsp;: <span class=\"kw-chiffre\">&gt; 13 ans</span>, nationalité française, pas sous tutelle)</li>\n                <li>Ou oralement, avec attestation <strong>écrite, datée et signée</strong> de l'entourage</li>\n                <li>Seul un <span class=\"kw-clinique\">droit d'opposition</span> est reconnu (l'absence d'opposition ne suffit pas à <em>autoriser</em>, mais l'opposition suffit à <em>s'opposer</em>)</li>\n              </ul>\n              Si le médecin n'a pas connaissance de la volonté du défunt, il doit <strong>s'efforcer de recueillir le témoignage des proches</strong>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Respect dû au corps</strong></td>\n            <td>Obl<span class=\"kw-chiffre\">iga</span>tion de « <span class=\"kw-clinique\">s'assurer de la meilleure restauration possible du corps</span> » ; obligation d'informer <span class=\"kw-clinique\">les</span> proches de la finalité des prélèvements</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Obstacle médico-légal.</strong> Un obstacle médico-légal à l'inhumation n'est <strong>pas une <span class=\"kw-ci\">contre-indication</span> absolue</strong> au prélèvement multi-organes (PMO). En cas d'obstacle (ex. mort encéphalique sur traumatisme crânien de circonstances inconnues) → nécessité d'une <span class=\"kw-alerte\">autorisation du Procureur de la République</span> ⭐. Un examen externe par un médecin légiste est réalisé avant le PMO.\n      </div>\n\n      <div class=\"callout callout-danger\">\n        <strong>Distracteurs classiques (prélèvement sur personne décédée).</strong>\n        <ul>\n          <li>Le <span class=\"kw-alerte\">comité d'experts n'intervient pas</span> pour <span class=\"kw-clinique\">les</span> prélèvements chez les personnes décédées (il autorise les prélèvements chez les <em>vivants</em>)</li>\n          <li>Le <span class=\"kw-alerte\">président du tribunal judiciaire n'intervient pas</span> pour <span class=\"kw-clinique\">les</span> personnes décédées (il recueille le consentement des donneurs <em>vivants</em>)</li>\n          <li><em>QCM Hermès</em>&nbsp;: <strong>seule une personne décédée</strong> peut faire un don à des fins scientifiques (une personne vivante ne le peut pas)</li>\n        </ul>\n      </div>","frequence":1},{"id":"201-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de prise en charge du donneur vivant","contenu":"<div class=\"callout callout-info\">\n        <strong>Avantages du donneur vivant.</strong>\n        <ul>\n          <li><span class=\"kw-clinique\">Meilleure survie à long terme</span> de l'organe transplanté</li>\n          <li>Moyen de lutte contre la pénurie ; réduit l'attente ; rend possible la transplantation <span class=\"kw-clinique\">préemptive</span> (avant l'épuration extra-rénale)</li>\n          <li>Permet <span class=\"kw-clinique\">les</span> transplantations imposant une préparation spécifique&nbsp;: <span class=\"kw-def\">ABO-incompatible</span>, désensibilisation d'un receveur porteur d'AC anti-HLA</li>\n        </ul>\n      </div>\n\n      <table >\n        <thead>\n          <tr><th>Modalité</th><th>Règle</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Pré-requis du donneur</strong></td>\n            <td>\n              <ul>\n                <li>Être <span class=\"kw-clinique\">majeur</span> et <strong>non sous protection légale</strong></li>\n                <li>Don <span class=\"kw-clinique\">gratuit, libre, consenti</span>, avec PEC des frais (pas de rémunération même en cas de pénurie)</li>\n                <li>Dons possibles&nbsp;: organe <span class=\"kw-clinique\">double</span> (rein, poumon) ou organe <span class=\"kw-clinique\">se régénérant</span> (foie)</li>\n                <li>Évaluation médicale pré-don (absence de pathologie, minimisation des risques)</li>\n                <li><em>QCM Hermès</em>&nbsp;: une personne vivante <strong>ne peut pas</strong> faire de don d'organe à des fins scientifiques</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Qui peut donner ? ⭐</strong></td>\n            <td>\n              <ul>\n                <li><strong>Cercle familial restreint</strong>&nbsp;: père, mère, frère, sœur, fils, fille</li>\n                <li><strong>Dérogation</strong>&nbsp;: conjoint, beaux-parents, grands-parents, oncle/tante, neveu/nièce, cousin germain</li>\n                <li>Toute personne prouvant une <span class=\"kw-clinique\">vie commune ≥ 2 ans</span> OU un <span class=\"kw-clinique\">lien affectif étroit et stable ≥ 2 ans</span> avec le receveur</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Don croisé ⭐</strong> (autorisé)</td>\n            <td>Lorsque <span class=\"kw-chiffre\">2</span> candidats au don sont <strong>incompatibles avec leur proche</strong>&nbsp;: <span class=\"kw-clinique\">les</span> donneurs échangent leurs receveurs respectifs s'ils sont compatibles. Possibilité d'une <strong>chaîne d'au maximum 6 paires</strong> donneur-receveur.</td>\n          </tr>\n          <tr>\n            <td><strong>Préalable légal</strong></td>\n            <td>\n              <ul>\n                <li><strong>Consentement</strong> (révocable à tout moment) recueilli par le <span class=\"kw-clinique\">président du tribunal judiciaire</span>, ou le <span class=\"kw-clinique\">procureur de la République en cas d'urgence</span> ⭐</li>\n                <li>Autorisation par un <strong>comité d'experts « comité donneur vivant »</strong> ⭐ qui apprécie la justification médicale, <span class=\"kw-clinique\">les</span> risques, et vérifie l'absence de pression</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Donneur vivant mineur ou majeur protégé.</strong> Prélèvement d'<span class=\"kw-alerte\">organes interdit</span> — <strong>sauf la moelle osseuse</strong> dans certains cas&nbsp;:\n        <ul>\n          <li><strong>Frère ou sœur</strong> — possible « en l'absence d'autre solution thérapeutique » ⭐</li>\n          <li><strong>Parents, cousin germain, oncle/tante, neveu/nièce</strong> — à titre exceptionnel ⭐</li>\n          <li>Conditions&nbsp;: autorisation d'un <span class=\"kw-clinique\">comité d'experts</span>, consentement devant le président du tribunal judiciaire (ou procureur si <span class=\"kw-alerte\">urgence</span>) ; pour le majeur sous tutelle&nbsp;: décision du <span class=\"kw-clinique\">juge des tutelles</span></li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>Don de moelle osseuse chez le donneur vivant majeur.</strong>\n        <ul>\n          <li><strong>Don familial</strong> (frère/sœur)&nbsp;: <span class=\"kw-clinique\">pas d'autorisation du comité d'experts requise</span> ❌ ; consentement devant le président du tribunal (ou procureur si <span class=\"kw-alerte\">urgence</span>)</li>\n          <li><strong>Don anonyme</strong> (registre France Greffe de moelle)&nbsp;: âge <span class=\"kw-chiffre\">18–51 ans</span> ; <span class=\"kw-clinique\">autorisation par un comité d'experts</span> ✅ + consentement devant le président du tribunal (ou procureur si <span class=\"kw-alerte\">urgence</span>)</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>Don de gamètes chez le donneur vivant majeur.</strong>\n        <ul>\n          <li>Don <span class=\"kw-clinique\">gratuit</span> ⭐ et <span class=\"kw-clinique\">anonyme</span> ⭐ ; règles de sécurité sanitaire (<span class=\"kw-def\">dépistage</span> <span class=\"kw-etio\">infectieux</span>)</li>\n          <li>Âge&nbsp;: <span class=\"kw-chiffre\">18–45 ans</span> (homme), <span class=\"kw-chiffre\">18–37 ans</span> (femme) ⭐ ; caryotype normal, enquête <span class=\"kw-etio\">génétique</span></li>\n          <li>Consentement <span class=\"kw-clinique\">écrit</span> (révocable jusqu'à l'utilisation des gamètes) ; réalisé principalement en <span class=\"kw-clinique\">CECOS</span></li>\n          <li><span class=\"kw-alerte\">Aucun lien de filiation</span> entre le donneur et l'enfant ⭐ ; il n'est pas obl<span class=\"kw-chiffre\">iga</span>toire de révéler à l'enfant qu'il est né d'un don (choix des parents) ⭐</li>\n          <li>Depuis <span class=\"kw-chiffre\">2021</span>&nbsp;: toute personne issue d'un don peut accéder, à sa majorité, à l'identité/données non identifiantes du donneur (qui doit y consentir)</li>\n          <li>Pénurie → délai d'attente de <span class=\"kw-chiffre\">18 à 24 mois</span> pour <span class=\"kw-clinique\">les</span> couples</li>\n        </ul>\n      </div>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong>Temps d'ischémie froide <span class=\"q\">— le compte à rebours du greffon</span></strong></p><p>un <span class=\"kw-bio\">cross-match virtuel</span> négatif évite d'attendre le cross-match réel (qui allonge l'ischémie froide)</p><ul><li>Délai entre le <span class=\"kw-clinique\">clampage vasculaire</span> chez le donneur et le <span class=\"kw-clinique\">déclampage</span> chez le receveur</li><li>Tolérance : <span class=\"kw-chiffre\">4 h</span> pour le cœur et <span class=\"kw-clinique\">les</span> poumons · jusqu'à <span class=\"kw-chiffre\">36 h</span> pour le rein</li></ul><p><strong>Traitement anti-rejet</strong></p><p>ne pas attendre la reprise de la <span class=\"kw-clinique\">diurèse</span></p><ul><li><span class=\"kw-ttt\">Traitement d'induction</span> débuté <span class=\"kw-alerte\">dès la réalisation de la greffe</span></li></ul><p><strong>Rejet hyperaigu humoral</strong></p><p><span class=\"kw-ttt\">transplantectomie</span> rapide souvent nécessaire (traitement médical souvent vain)</p><ul><li>Dû à des <span class=\"kw-etio\">AC anti-HLA préformés</span> → <span class=\"kw-alerte\">thrombose du greffon</span></li><li>Survenue en quelques <span class=\"kw-chiffre\">minutes</span> (immédiat) à <span class=\"kw-chiffre\">4–5 jours</span> (différé)</li></ul><p><strong>Constat de la mort (donneur décédé)</strong></p><ul><li><span class=\"kw-def\">Mort encéphalique</span> : <span class=\"kw-bio\">2 EEG</span> à <span class=\"kw-chiffre\">≥ 4 h</span> d'intervalle, nuls et aréactifs sur <span class=\"kw-chiffre\">30 min</span> (ou angio-imagerie)</li><li><span class=\"kw-def\">Donneur à cœur arrêté</span> : <span class=\"kw-bio\">ECG</span> sur <span class=\"kw-chiffre\">5 min</span> sans QRS + interrogation <span class=\"kw-alerte\">immédiate du registre des refus</span></li></ul>","hospit":"<p><strong>Inscription sur liste d'attente</strong></p><ul><li>Greffe possible seulement si <span class=\"kw-clinique\">couvert par la Sécurité sociale</span></li><li>ET <span class=\"kw-clinique\">inscrit sur la liste nationale</span> de l'<span class=\"kw-def\">Agence de la Biomédecine</span></li></ul><p><strong>Attribution du greffon <span class=\"q\">— par l'ABM</span></strong></p><ul><li><span class=\"kw-def\">Système de score</span> : principe d'<span class=\"kw-def\">utilité</span> (efficacité) + principe de <span class=\"kw-def\">justice</span> (équité)</li><li>Critères : compatibilité <span class=\"kw-bio\">ABO / HLA</span>, ischémie froide la plus courte, durée d'attente, taille (thorax / foie)</li></ul><p><strong><span class=\"kw-def\">Critères de</span> priorité</strong></p><ul><li>Receveur <span class=\"kw-clinique\">pédiatrique</span></li><li>Degré d'<span class=\"kw-alerte\">urgence</span> (ex. <span class=\"kw-alerte\">hépatite fulminante</span>)</li><li>Receveur <span class=\"kw-clinique\">hyperimmunisé</span> (difficile à apparier)</li></ul>","redflags":"<ul><li><span class=\"kw-bio\">Cross-match réel positif</span> (lyse cellulaire) → <span class=\"kw-ci\">contre-indique la transplantation</span></li><li><span class=\"kw-def\">ABO-incompatible</span> sans désensibilisation → <span class=\"kw-alerte\">rejet hyperaigu avec nécrose immédiate du greffon</span></li><li><span class=\"kw-etio\">AC anti-HLA préformés</span> dirigés contre le donneur → <span class=\"kw-alerte\">FR majeur de rejet humoral</span></li><li><span class=\"kw-alerte\">Arrêt ou inobservance de l'immunosuppression</span> → rejet aigu (ne JAMAIS arrêter)</li><li><span class=\"kw-ci\">CI absolues</span> au prélèvement (donneur) : <span class=\"kw-ci\">infection transmissible non contrôlée</span> (<span class=\"kw-etio\">tuberculose</span>, rage, <span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">VHC</span>, HTLV), <span class=\"kw-ci\">Creutzfeldt-Jakob</span>, <span class=\"kw-ci\">cancer / hémopathie</span></li></ul>","principes":"<p>Le rejet du greffon survient <span class=\"kw-alerte\">inéluctablement sans immunosuppression</span> : traitement <strong>à vie</strong>, à <span class=\"kw-alerte\">ne JAMAIS arrêter</span>. Cible principale = l'<span class=\"kw-clinique\">activation et la prolifération des lymphocytes T</span>. Attention aux <span class=\"kw-alerte\">interactions médicamenteuses</span> (inhibiteurs / inducteurs du <span class=\"kw-bio\">cytochrome P450 3A4</span>).</p><p><strong>Traitement d'induction</strong></p><ul><li>Immunosuppression <span class=\"kw-alerte\">forte</span> <span class=\"kw-clinique\">les</span> 1ᵉʳˢ jours</li><li><span class=\"kw-ttt\">AC polyclonaux déplétants</span> (haut risque immunologique) ou <span class=\"kw-ttt\">basiliximab</span> (anti-CD25 non déplétant)</li></ul><p><strong>Traitement d'entretien <span class=\"q\">— <span class=\"kw-ttt\">trithérapie</span> de référence</span></strong></p><ul><li><span class=\"kw-ttt\">Corticoïdes</span> + <span class=\"kw-ttt\">mycophénolate</span> + <span class=\"kw-ttt\">tacrolimus</span> (ou <span class=\"kw-ttt\">ciclosporine</span>)</li><li>Alternatives : <span class=\"kw-ttt\">inhibiteurs de mTOR</span> ou <span class=\"kw-ttt\">bélatacept</span> (limitent la néphrotoxicité des ICN ou <span class=\"kw-clinique\">les</span> EI des <span class=\"kw-ttt\">corticoïdes</span>)</li></ul><p><strong>Traitement des rejets</strong></p><ul><li>Rejet aigu <span class=\"kw-clinique\">cellulaire</span> : <span class=\"kw-ttt\">corticoïdes fortes doses</span> (bon <span class=\"kw-def\">pronostic</span>)</li><li>Rejet aigu <span class=\"kw-clinique\">humoral</span> : <span class=\"kw-ttt\">échanges plasmatiques</span> + <span class=\"kw-ttt\">Ig polyvalentes</span> ± <span class=\"kw-ttt\">rituximab</span></li><li>Rejet <span class=\"kw-alerte\">hyperaigu</span> : <span class=\"kw-ttt\">transplantectomie</span></li></ul><p><strong>Désensibilisation <span class=\"q\">— ABO-incompatible / receveur immunisé</span></strong></p><p>rend possibles <span class=\"kw-clinique\">les</span> greffes <span class=\"kw-def\">ABO-incompatibles</span></p><ul><li>Réduire le titre d'<span class=\"kw-etio\">alloanticorps</span> : <span class=\"kw-ttt\">plasmaphérèse</span>, <span class=\"kw-ttt\">rituximab</span></li><li>Neutraliser leur effet cytotoxique : <span class=\"kw-ttt\">immunoglobulines polyvalentes</span>, <span class=\"kw-ttt\">bloqueurs du complément</span></li></ul>","suivi":"<p><strong>Receveur en attente de greffe</strong></p><ul><li>Recherche d'<span class=\"kw-etio\">AC anti-HLA</span> <span class=\"kw-chiffre\">tous les 3 mois</span> pendant l'attente</li></ul><p><strong>Sous immunosuppression</strong></p><ul><li><span class=\"kw-bio\">Monitoring pharmacologique</span> (dosage sanguin) des molécules à <span class=\"kw-clinique\">marge thérapeutique étroite</span></li><li><span class=\"kw-def\">Surveillance</span> <span class=\"kw-clinique\">cutanée</span> systématique <span class=\"kw-chiffre\">1×/an</span> → risque de <span class=\"kw-etio\">carcinome épidermoïde</span></li></ul><p><strong>Post-greffe rénale (immédiat)</strong></p><ul><li><span class=\"kw-clinique\">Sonde vésicale</span> <span class=\"kw-clinique\">les</span> 1ᵉʳˢ jours (vérifier la reprise de <span class=\"kw-clinique\">diurèse</span>)</li><li><span class=\"kw-clinique\">Sonde JJ</span> <span class=\"kw-clinique\">les</span> 1ʳᵉˢ semaines (cicatrisation de l'anastomose urétéro-vésicale)</li></ul><p><strong>Donneur vivant</strong></p><ul><li><span class=\"kw-clinique\">Suivi annuel</span> du donneur après le don</li></ul><p><strong>Récidive de la néphropathie sur le greffon <span class=\"q\">— DD du rejet</span></strong></p><ul><li>Récidive avec <span class=\"kw-alerte\">perte du greffon</span> : <span class=\"kw-etio\">HSF</span>, <span class=\"kw-etio\">SHU atypique</span></li><li>Récidive sans perte : <span class=\"kw-etio\">GEM</span>, <span class=\"kw-etio\">néphropathie à IgA</span>, <span class=\"kw-etio\">lupus</span>, <span class=\"kw-etio\">GNRP pauci-immunes</span></li></ul>"},"liensGlobaux":[{"href":"https://www.urofrance.org/lafu-academie/formation-du-college/referentiel-du-college-durologie-6eme-edition/chapitre-12-item-201-transplantation-dorganes","label":"urofrance.org"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/18-ch09-101-110-9782294769580.pdf","label":"ce-mir.fr"}],"cards":[{"i":"0102a61851e0","n":201,"o":"201-1","u":"Définition","t":"Connaître la définition de donneurs potentiels","q":"Quel est le principe de consentement appliqué en France pour le don d'organes post-mortem ?","a":"<p>En France, le principe est celui du <strong>consentement présumé</strong> : toute personne décédée est considérée comme donneuse par défaut, sauf opposition exprimée de son vivant.</p>"},{"i":"04b3c2c6a8d5","n":201,"o":"201-1","u":"Définition","t":"Connaître la définition de donneurs potentiels","q":"Quelle est la définition d'un donneur potentiel dans le contexte de la transplantation d'organes ?","a":"<p>Un donneur potentiel est <strong>toute personne (vivante ou décédée)</strong> chez qui un prélèvement d'organe(s) et/ou de tissu(s) peut être envisagé en vue d'une transplantation.</p>"},{"i":"584fc5be1d42","n":201,"o":"201-1","u":"Définition","t":"Connaître la définition de donneurs potentiels","q":"Quels sont les catégories de donneurs décédés et leurs particularités ?","a":"<ul><li><strong>Donneur décédé en état de mort encéphalique (EME)</strong> : destruction définitive et irréversible de l'encéphale avec perfusion des autres organes maintenue. C'est la situation la plus fréquente des prélèvements multi-organes (PMO).</li><li><strong>Donneur décédé en arrêt circulatoire (« donneur à cœur arrêté »)</strong> : personne décédée en arrêt circulatoire persistant, classée selon la classification de Maastricht. L'essentiel des prélèvements relève d'une procédure <strong>Maastricht 3</strong> (après limitation des thérapeutiques).</li></ul>"},{"i":"9717ce955b13","n":201,"o":"201-1","u":"Définition","t":"Connaître la définition de donneurs potentiels","q":"Quelles sont les principales catégories de contre-indications absolues au prélèvement d'organes ?","a":"<ul><li><strong>Maladie infectieuse transmissible non contrôlée ou évolutive</strong> : tuberculose active, rage, <strong>VIH</strong>, <strong>VHC</strong>, <strong>HTLV</strong>.</li><li>Suspicion d'<strong>encéphalopathie spongiforme subaiguë</strong> (Creutzfeldt-Jakob).</li><li><strong>Cancer</strong> ou hémopathie (sauf certains cancers anciens guéris).</li></ul>"},{"i":"987ee4760a57","n":201,"o":"201-1","u":"Définition","t":"Connaître la définition de donneurs potentiels","q":"Quels sont les éléments systématiquement recherchés lors du bilan pré-greffe d'un donneur potentiel ?","a":"<ul><li><strong>Bilan infectieux</strong> : dépistage obligatoire <strong>VIH1, VIH2, VHB, VHC, syphilis, HTLV1, CMV, EBV, Toxoplasma gondii</strong>. Une pathologie transmissible n'est pas toujours une contre-indication.</li><li><strong>Bilan néoplasique</strong> : un antécédent de cancer est une contre-indication relative ; <strong>TDM-TAP</strong> systématique.</li><li><strong>Qualité des organes</strong> : paramètres biologiques et morphologiques, anatomopathologie extemporanée, machine de perfusion, temps d'ischémie froide.</li><li>Autres : groupage sanguin, typage HLA, AC anti-HLA chez le receveur, évaluation cardiovasculaire.</li></ul>"},{"i":"25cee6b02cff","n":201,"o":"201-10","u":"Définition","t":"Connaître les principes éthiques et légaux en matière de don d’organes","q":"Quelles sont les obligations en matière de respect du corps du défunt lors d'un prélèvement d'organes ?","a":"<p>Il y a une <strong>obligation de s'assurer de la meilleure restauration possible du corps</strong> après le prélèvement. De plus, les proches doivent être informés de la finalité des prélèvements effectués.</p>"},{"i":"55cdd03638c3","n":201,"o":"201-10","u":"Définition","t":"Connaître les principes éthiques et légaux en matière de don d’organes","q":"Quel est le principe de gratuité en matière de don d'organes en France ?","a":"<p>Le principe de gratuité signifie que les dons d'organes sont <strong>interdits de toute rémunération</strong>, même en cas de pénurie. Toute publicité est également proscrite, et les frais liés au don sont pris en charge.</p>"},{"i":"56b32645e8f4","n":201,"o":"201-10","u":"Définition","t":"Connaître les principes éthiques et légaux en matière de don d’organes","q":"Qu'est-ce que le consentement présumé en matière de don d'organes en France ?","a":"<p>Le consentement présumé signifie que <strong>toute personne décédée est considérée comme donneuse par défaut</strong>, sauf si elle a exprimé son opposition de son vivant. Cette opposition peut être formulée de deux manières :</p><ul><li>Par inscription sur le <strong>registre national des refus</strong> (révocable, pour les personnes de plus de 13 ans de nationalité française et non sous tutelle, géré par l'ABM).</li><li><strong>Oralement</strong>, à condition qu'il y ait une attestation écrite, datée et signée de l'entourage du défunt.</li></ul><p>Si la volonté du défunt n'est pas connue, le médecin doit s'efforcer de recueillir le témoignage de ses proches.</p>"},{"i":"90bfbfcefcf5","n":201,"o":"201-10","u":"Définition","t":"Connaître les principes éthiques et légaux en matière de don d’organes","q":"Quel est l'impact d'un obstacle médico-légal sur un prélèvement multi-organes (PMO) ?","a":"<p>Un obstacle médico-légal (par exemple, un décès survenu dans des circonstances inconnues et nécessitant une enquête judiciaire) <strong>n'est pas une contre-indication absolue</strong> à un prélèvement multi-organes. Dans ce cas, une <strong>autorisation du Procureur de la République est nécessaire</strong>. Un examen externe par un médecin légiste est également effectué avant le PMO.</p>"},{"i":"a513af068ca4","n":201,"o":"201-10","u":"Définition","t":"Connaître les principes éthiques et légaux en matière de don d’organes","q":"Comment fonctionne le principe de l'anonymat entre donneur et receveur d'organes ?","a":"<p>L'anonymat est <strong>strict entre le donneur et le receveur</strong>, signifiant que le nom de l'un ne peut être communiqué à l'autre. Ce principe s'applique aux donneurs décédés, mais aussi aux dons de moelle osseuse, de sang et de gamètes.</p><p>Il existe <strong>deux dérogations</strong> :</p><ul><li>Lors d'un don sur personne vivante au sein d'une même famille.</li><li>En cas de nécessité thérapeutique où seuls les médecins du donneur et du receveur peuvent accéder à l'identification.</li></ul><p>La famille du donneur peut demander à être informée des organes prélevés et des résultats des greffes, sans pour autant connaître l'identité du receveur.</p>"},{"i":"237c80c61e33","n":201,"o":"201-11","u":"Prise en charge","t":"Connaître les modalités de prise en charge du donneur vivant","q":"Quels sont les pré-requis légaux pour un donneur d'organe vivant en France ?","a":"<p>Les pré-requis légaux pour un donneur d'organe vivant en France sont :</p>\n<ul>\n<li>Le donneur doit être <strong>majeur</strong> et non sous protection légale.</li>\n<li>Le don doit être <strong>gratuit, libre et consenti</strong>. Les frais sont pris en charge mais aucune rémunération n'est autorisée.</li>\n<li>Les dons possibles concernent les <strong>organes doubles</strong> (rein, poumon) ou les <strong>organes se régénérant</strong> (foie).</li>\n<li>Une <strong>évaluation médicale pré-don</strong> est obligatoire pour s'assurer de l'absence de pathologie et minimiser les risques.</li>\n<li>Le consentement est recueilli par le <strong>président du tribunal judiciaire</strong> ou le procureur de la République en cas d'urgence, et est révocable à tout moment.</li>\n<li>Une <strong>autorisation par un comité d'experts</strong> (« comité donneur vivant ») est requise, s'assurant de la justification médicale, des risques et de l'absence de pression.</li>\n</ul>"},{"i":"4da9d918556c","n":201,"o":"201-11","u":"Prise en charge","t":"Connaître les modalités de prise en charge du donneur vivant","q":"Quelles sont les conditions du don de gamètes chez le donneur vivant majeur en France ?","a":"<p>Le don de gamètes chez le donneur vivant majeur est soumis aux conditions suivantes :</p>\n<ul>\n<li>Le don est <strong>gratuit et anonyme</strong>.</li>\n<li>Des règles de <strong>sécurité sanitaire</strong> (dépistage infectieux) sont appliquées.</li>\n<li>L'âge du donneur doit être entre <strong>18 et 45 ans pour un homme</strong>, et entre <strong>18 et 37 ans pour une femme</strong>.</li>\n<li>Le caryotype doit être normal et une enquête génétique réalisée.</li>\n<li>Un <strong>consentement écrit</strong> est requis, révocable jusqu'à l'utilisation des gamètes.</li>\n<li><strong>Aucun lien de filiation</strong> ne doit être établi entre le donneur et l'enfant né du don.</li>\n<li>Depuis 2021, l'enfant issu d'un don peut accéder, à sa majorité, à l'identité et aux données non identifiantes du donneur, si ce dernier y a consenti.</li>\n</ul>"},{"i":"6e31e66fcdc1","n":201,"o":"201-11","u":"Prise en charge","t":"Connaître les modalités de prise en charge du donneur vivant","q":"Quelles sont les spécificités du don de moelle osseuse chez le donneur vivant majeur en France ?","a":"<p>Les spécificités du don de moelle osseuse chez le donneur vivant majeur sont :</p>\n<ul>\n<li><strong>Don familial</strong> (frère/sœur) : ne nécessite <strong>pas d'autorisation du comité d'experts</strong>. Le consentement est recueilli devant le président du tribunal (ou procureur si urgence).</li>\n<li><strong>Don anonyme</strong> (registre France Greffe de Moelle) : le donneur doit avoir entre <strong>18 et 51 ans</strong>. Nécessite une <strong>autorisation par un comité d'experts</strong> et un consentement devant le président du tribunal (ou procureur si urgence).</li>\n</ul>"},{"i":"8e511ad5b135","n":201,"o":"201-11","u":"Prise en charge","t":"Connaître les modalités de prise en charge du donneur vivant","q":"Quels sont les avantages du don d'organe par donneur vivant en transplantation ?","a":"<p>Les avantages du don d'organe par donneur vivant sont :</p>\n<ul>\n<li>Une <strong>meilleure survie à long terme</strong> de l'organe transplanté.</li>\n<li>Une <strong>réduction de l'attente</strong> et une lutte contre la pénurie d'organes.</li>\n<li>La possibilité d'une <strong>transplantation préemptive</strong> (avant l'épuration extra-rénale).</li>\n<li>La réalisation de transplantations nécessitant une préparation spécifique (<strong>ABO-incompatible</strong>, <strong>désensibilisation</strong> chez des receveurs porteurs d'anticorps anti-HLA).</li>\n</ul>"},{"i":"cbae35fa4159","n":201,"o":"201-11","u":"Prise en charge","t":"Connaître les modalités de prise en charge du donneur vivant","q":"Sous quelles conditions un mineur ou un majeur protégé peut-il être donneur d'organe en France ?","a":"<p>Le prélèvement d'organes est <strong>interdit</strong> chez un mineur ou un majeur protégé, <strong>sauf pour la moelle osseuse</strong> dans certains cas spécifiques :</p>\n<ul>\n<li>Don de moelle osseuse à un <strong>frère ou une sœur</strong> : possible « en l'absence d'autre solution thérapeutique ».</li>\n<li>Don de moelle osseuse à des <strong>parents, cousin germain, oncle/tante, neveu/nièce</strong> : à titre exceptionnel.</li>\n<li>Les conditions sont : une <strong>autorisation d'un comité d'experts</strong>, et un <strong>consentement devant le président du tribunal judiciaire</strong> (ou procureur si urgence). Pour un majeur sous tutelle, la décision revient au <strong>juge des tutelles</strong>.</li>\n</ul>"},{"i":"cce16f117b9e","n":201,"o":"201-11","u":"Prise en charge","t":"Connaître les modalités de prise en charge du donneur vivant","q":"Qui peut être donneur d'organe vivant en France selon la législation ?","a":"<p>Les personnes pouvant être donneurs d'organe vivant sont :</p>\n<ul>\n<li>Le <strong>cercle familial restreint</strong> : père, mère, frère, sœur, fils, fille.</li>\n<li>Par dérogation, le <strong>conjoint</strong>, les beaux-parents, grands-parents, oncle/tante, neveu/nièce, cousin germain.</li>\n<li>Toute personne prouvant une <strong>vie commune <ins>&ge; 2 ans</ins></strong> ou un <strong>lien affectif étroit et stable <ins>&ge; 2 ans</ins></strong> avec le receveur.</li>\n<li>Le <strong>don croisé</strong> est autorisé si deux paires donneur-receveur sont incompatibles, permettant l'échange des organes. Une chaîne peut comprendre jusqu'à <strong>6 paires</strong>.</li>\n</ul>"},{"i":"18f05a901163","n":201,"o":"201-2","u":"Définition","t":"Connaître la définition des tissus et organes transplantés","q":"Quelle est la définition d'une greffe de tissus en médecine ?","a":"<p>La greffe de tissus est une opération permettant une <strong>reconstruction tissulaire</strong> par l'implantation de tissus sains (comme la <strong>cornée</strong>, la <strong>peau</strong>, les <strong>os</strong> ou les <strong>vaisseaux</strong>) prélevés chez un donneur décédé ou vivant. Elle repose sur une <strong>simple apposition tissulaire</strong>, à l'exception de la greffe de tissus composites.</p>"},{"i":"2f754a5ec0e6","n":201,"o":"201-2","u":"Définition","t":"Connaître la définition des tissus et organes transplantés","q":"Quelle est la définition d'une transplantation d'organe en médecine ?","a":"<p>La transplantation d'organe est une <strong>opération chirurgicale</strong> consistant à remplacer un organe vital défaillant par un organe sain (greffon ou transplant) prélevé chez un donneur. Elle nécessite des <strong>sutures vasculaires</strong> pour le rétablissement immédiat de la vascularisation du greffon.</p>"},{"i":"69139d64a2ae","n":201,"o":"201-2","u":"Définition","t":"Connaître la définition des tissus et organes transplantés","q":"Quelle est la distinction clé entre la transplantation d'organe et la greffe de tissus, et quelles en sont les exceptions notables ?","a":"<p>La distinction clé est que la transplantation d'organe implique impérativement des <strong>sutures vasculaires</strong> pour rétablir immédiatement la vascularisation du greffon. En revanche, la greffe de tissus repose généralement sur une <strong>simple apposition tissulaire</strong>.</p><ul><li>Une exception notable est la <strong>greffe de tissus composites</strong> (visage, membres), qui nécessite aussi des <strong>sutures vasculaires ET nerveuses</strong>.</li><li>La <strong>greffe d'îlots de Langerhans</strong> est acceptée dans le soin courant pour des indications bien circonscrites.</li></ul>"},{"i":"3d28e33e1368","n":201,"o":"201-5","u":"Définition","t":"Connaître les grands principes de la loi de bio-éthique concernant le don d’organe","q":"Comment a évolué le cercle des donneurs vivants depuis la loi de bioéthique de 1994 en France ?","a":"<p>Initialement, en 1994, les donneurs vivants étaient limités aux <strong>majeurs et apparentés</strong> (parents, enfants, fratrie). La 1<sup>re</sup> révision en 2004 a élargi ce cercle aux grands-parents, oncle/tante, cousin germain, conjoint, ou toute personne prouvant une <strong>vie commune <span class=\"text-decoration-underline\">≥ 2 ans</span></strong>. La 2<sup>e</sup> révision en 2011 a permis d'inclure toute personne prouvant un <strong>lien affectif étroit et stable <span class=\"text-decoration-underline\">≥ 2 ans</span></strong> avec le receveur, et a introduit les dons croisés de reins.</p>"},{"i":"5745120ba5f0","n":201,"o":"201-5","u":"Définition","t":"Connaître les grands principes de la loi de bio-éthique concernant le don d’organe","q":"Quel est le principe fondamental en matière de consentement pour le don d'organes d'une personne décédée en France ?","a":"<p>Le principe fondamental est celui du <strong>consentement présumé</strong>, introduit par la loi Caillavet de 1976. Cela signifie que toute personne est considérée comme consentante au don d'organes après son décès, sauf si elle a exprimé son refus de son vivant (par exemple, en s'inscrivant au Registre National des Refus).</p>"},{"i":"f4218589f075","n":201,"o":"201-5","u":"Définition","t":"Connaître les grands principes de la loi de bio-éthique concernant le don d’organe","q":"Quels sont les grands principes transverses des lois de bioéthique françaises concernant le don et la transplantation d'organes ?","a":"<ul><li>La <strong>gratuité du don</strong> et l'interdiction de toute publicité.</li><li>L'<strong>anonymat</strong> entre le donneur et le receveur.</li><li>Le <strong>consentement présumé</strong> pour le donneur décédé et le consentement libre et éclairé pour le donneur vivant.</li><li>Le <strong>respect dû au corps</strong> du défunt, avec l'obligation de restaurer le corps au mieux.</li><li>La définition des modalités de constatation de la mort et l'obligation d'informer les proches.</li></ul>"},{"i":"8bc655cf3b1b","n":201,"o":"201-6","u":"Définition","t":"Connaître la définition de la mort encéphalique","q":"Quelles sont les particularités de la mort encéphalique qui la rendent essentielle pour le prélèvement d'organes ?","a":"<p>La particularité de la mort encéphalique est la <strong>dissociation entre un encéphale définitivement détruit</strong> et des <strong>organes périphériques encore perfusés</strong> (cœur battant, ventilation mécanique). C'est précisément cette dissociation qui rend possible le prélèvement multi-organes.</p>"},{"i":"df9fd2b93fbd","n":201,"o":"201-6","u":"Définition","t":"Connaître la définition de la mort encéphalique","q":"Quelle est la définition de la mort encéphalique (EME) ?","a":"<p>La mort encéphalique (EME), aussi appelée mort cérébrale, correspond à la <strong>destruction définitive et irréversible de l'encéphale</strong>, alors que la perfusion des autres organes est maintenue.</p>"},{"i":"e179bbc476be","n":201,"o":"201-6","u":"Définition","t":"Connaître la définition de la mort encéphalique","q":"Quelles sont les principales causes de mort encéphalique ?","a":"<ul><li>Les <strong>accidents vasculaires cérébraux (AVC)</strong>, représentant plus de 50 % des cas.</li><li>Les <strong>accidents de la circulation</strong> et autres traumatismes.</li><li>Les <strong>anoxies cérébrales</strong> (par exemple, pendaisons, noyades).</li><li>Les <strong>intoxications</strong>.</li></ul>"}]};